import mysql from 'mysql2/promise';
import bcrypt from 'bcryptjs';

let pool: mysql.Pool | null = null;
let isInitialized = false;

export const createConnectionPool = () => {
  // Strict sync with .env generated by launcher.js
  const host = process.env.DB_HOST;
  const user = process.env.DB_USER;
  const password = process.env.DB_PASS;
  const database = process.env.DB_NAME;
  
  if (!database) {
    console.error("[CRITICAL ERROR] DB_NAME tidak ditemukan di environment variables! Pastikan file .env terbaca.");
  }

  if (pool) pool.end().catch(() => {});
  pool = mysql.createPool({ host, user, password, database, enableKeepAlive: true, keepAliveInitialDelay: 10000, waitForConnections: true, connectionLimit: 50, queueLimit: 0, multipleStatements: true });
};

export const initDB = async () => {
  const host = process.env.DB_HOST;
  const user = process.env.DB_USER;
  const password = process.env.DB_PASS;
  const database = process.env.DB_NAME;

  if (!database) {
    console.error("[CRITICAL ERROR] DB_NAME kosong! Pastikan file .env terbaca dengan benar.");
    return;
  }

  while (!isInitialized) {
    try {
      console.log(`[DATABASE] Connecting to MySQL server to ensure database exists...`);
      // Hubungkan tanpa database target untuk create database
      const rootConnection = await mysql.createConnection({ host, user, password });
      await rootConnection.query(`CREATE DATABASE IF NOT EXISTS \`${database}\``);
      await rootConnection.end();

      console.log(`[DATABASE] Connecting to MySQL and targeting database '${database}'...`);
      // Hubungkan langsung dengan target database agar DDL tereksekusi pada tempat yang tepat
      const connection = await mysql.createConnection({ host, user, password, database });
      
      console.log('[DATABASE] Verifying and Creating Core Tables (Users & Videos)...');
      
      await connection.query(`
        CREATE TABLE IF NOT EXISTS Users (
          id INT AUTO_INCREMENT PRIMARY KEY,
          email VARCHAR(255) UNIQUE NOT NULL,
          password VARCHAR(255) NOT NULL,
          firstName VARCHAR(100),
          lastName VARCHAR(100),
          role ENUM('user', 'admin') DEFAULT 'user',
          avatar_url VARCHAR(255) NULL,
          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
      `);

      await connection.query(`
        CREATE TABLE IF NOT EXISTS Videos (
          id INT AUTO_INCREMENT PRIMARY KEY,
          user_id INT NOT NULL,
          title VARCHAR(255) NOT NULL,
          description TEXT,
          url VARCHAR(255),
          thumbnail_url VARCHAR(255),
          status VARCHAR(50) DEFAULT 'processing',
          processing_status VARCHAR(50) DEFAULT 'ready',
          visibility ENUM('public', 'private', 'unlisted') DEFAULT 'public',
          category_id INT DEFAULT 1,
          allow_download BOOLEAN DEFAULT TRUE,
          downloads INT DEFAULT 0,
          views INT DEFAULT 0,
          duration INT DEFAULT 0,
          student_name VARCHAR(255),
          program_id INT,
          meeting_number INT,
          session_date DATE,
          upload_id VARCHAR(255),
          file_path VARCHAR(255),
          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          FOREIGN KEY (user_id) REFERENCES Users(id) ON DELETE CASCADE
        )
      `);

      await connection.query(`
        CREATE TABLE IF NOT EXISTS subscriptions (
          id INT AUTO_INCREMENT PRIMARY KEY,
          subscriber_id INT NOT NULL,
          leader_id INT NOT NULL,
          created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
          UNIQUE KEY unique_sub (subscriber_id, leader_id)
        )
      `);

      // --- SYSTEM SETTINGS (GAMING MODE & RESOURCE CONTROL) ---
      await connection.query(`
        CREATE TABLE IF NOT EXISTS SystemSettings (
          setting_key VARCHAR(100) PRIMARY KEY,
          setting_value VARCHAR(255) NOT NULL,
          updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
        )
      `);

      await connection.query(`
        INSERT IGNORE INTO SystemSettings (setting_key, setting_value) 
        VALUES ('gaming_mode', 'false')
      `);

      console.log('[DATABASE] Core Auto-Migration Complete (Users, Videos, Subscriptions & SystemSettings tables ensured).');

      // Seed Default Admin User
      const [adminExists]: any = await connection.query(`SELECT id FROM Users WHERE email = 'admin@omnihub.com'`);
      const hashedAdminPassword = await bcrypt.hash('Admin#1234.', 10);
      if (adminExists.length === 0) {
        await connection.query(
          `INSERT INTO Users (email, password, firstName, lastName, role) VALUES (?, ?, 'System', 'Admin', 'admin')`,
          ['admin@omnihub.com', hashedAdminPassword]
        );
        console.log('[DATABASE] Default admin user (admin@omnihub.com) seeded successfully.');
      } else {
        await connection.query(
          `UPDATE Users SET password = ? WHERE email = 'admin@omnihub.com'`,
          [hashedAdminPassword]
        );
        console.log('[DATABASE] Default admin user (admin@omnihub.com) password updated.');
      }

      console.log('[DATABASE] Initialization Complete. MySQL is ready.');
      await connection.end();
      createConnectionPool();
      isInitialized = true;
    } catch (error: any) {
      console.error('[DATABASE] MySQL Initialization Failed, retrying in 5s...', error.message);
      await new Promise(res => setTimeout(res, 5000));
    }
  }
};

export const executeWithRetry = async (method: 'execute' | 'query', queryStr: string, params: any[] = []): Promise<any> => {
  if (!pool) throw new Error("MySQL Pool is not ready.");
  return await (pool as any)[method](queryStr, params);
};

const db = {
  execute: async (queryStr: string, params: any[] = []) => executeWithRetry('execute', queryStr, params),
  query: async (queryStr: string, params: any[] = []) => executeWithRetry('query', queryStr, params),
  end: async () => { if (pool) await pool.end(); }
};

export default db;
